"""Phase 12 gate: Mermaid generated by code — escaping + manual parse check."""
from mentor.features import mermaid as M


def test_escape_replaces_syntax_chars():
    import re
    label = M.escape_label('a"b[c]d{e}f|g#h<i>j`k;l')
    assert not any(c in label for c in '"[]{}|<>`'), label
    # `#` survives only inside `#entity;` codes, never bare.
    assert re.search(r"#(?![a-z0-9]+;)", label) is None, label
    assert "a" in label and "b" in label


def test_render_uses_generated_ids_and_shapes():
    model = {"nodes": [
        {"id": "N1", "kind": "entrypoint", "label": "app entrypoint"},
        {"id": "N2", "kind": "external-database",
         "label": 'db "main" [v2]'}],
        "edges": [{"from": "N1", "to": "N2", "kind": "imports"}]}
    text = M.render(model)
    assert text.startswith("flowchart LR\n")
    assert "([\"app entrypoint\"])" in text  # stadium for entrypoint
    assert '[("db #quot;main#quot; (v2)")]' in text  # cylinder + escaped
    assert "N1 -->|imports| N2" in text
    assert M.check(text) == []


def test_check_rejects_broken_diagrams():
    assert M.check("graph TD\n    A-->B") != []  # wrong header
    assert M.check("flowchart LR\n    N1 -->|x| N9") != []  # unknown endpoint
    assert M.check("flowchart LR\n    N1[bad [label]]") != []  # raw bracket


def test_no_end_or_link_target_confusion_by_construction():
    model = {"nodes": [{"id": "N1", "kind": "frontend", "label": "end oust"}],
             "edges": []}
    text = M.render(model)
    assert M.check(text) == []
    assert '"end oust"' in text  # quoted: `end` never parses as keyword
